root.querySelector('.eye').addEventListener('click', () => { pw.type = pw.type === 'password' ? 'text' : 'password'; });
f.addEventListener('submit', (e) => { e.preventDefault(); const a = set(em, /^\S+@\S+\.\S+$/.test(em.value) ? '' : 'Enter a valid email'); const b = set(pw, pw.value.length >= 8 ? '' : 'At least 8 characters'); if (a && b) root.querySelector('.go').textContent = 'Signed in ✓'; });
})();

