.c-empty-state-24{--bg:#effcf8;--surface:#ffffff;--text:#0b3a33;--muted:#44736b;--primary:#0b7d6b;--on-primary:#ffffff;--border:#cdeee6;--accent:#e8583a;--radius:28px;--radius-ctl:999px;--shadow:0 20px 50px rgba(0,0,0,.3);--font:-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;--pad:12px;--gap:8px}
.c-empty-state-24{box-sizing:border-box;font-family:var(--font);font-size:16px;line-height:1.5;color:var(--text);background:var(--bg);padding:var(--pad)}
.c-empty-state-24 *,.c-empty-state-24 *::before,.c-empty-state-24 *::after{box-sizing:inherit;margin:0}
.c-empty-state-24 button,.c-empty-state-24 input,.c-empty-state-24 textarea,.c-empty-state-24 select{font:inherit;color:inherit}
.c-empty-state-24 :focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.c-empty-state-24 .dz{display:grid;gap:4px;justify-items:center;width:min(100%,380px);padding:34px var(--pad);border:2px dashed var(--border);border-radius:var(--radius);cursor:pointer;text-align:center;transition:all .15s}.c-empty-state-24 .dz:hover{border-color:var(--primary);background:color-mix(in srgb,var(--primary) 6%,transparent)}.c-empty-state-24 small{color:var(--muted)}

.c-cta-24{--bg:#0a0a0f;--surface:#14141d;--text:#f5f5ff;--muted:#a5a5c0;--primary:#39ff88;--on-primary:#04130a;--border:#2a2a3c;--accent:#ff3df0;--radius:4px;--radius-ctl:4px;--shadow:0 1px 3px rgba(0,0,0,.14);--font:-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;--pad:12px;--gap:8px}
.c-cta-24{box-sizing:border-box;font-family:var(--font);font-size:16px;line-height:1.5;color:var(--text);background:var(--bg);padding:var(--pad)}
.c-cta-24 *,.c-cta-24 *::before,.c-cta-24 *::after{box-sizing:inherit;margin:0}
.c-cta-24 button,.c-cta-24 input,.c-cta-24 textarea,.c-cta-24 select{font:inherit;color:inherit}
.c-cta-24 :focus-visible{outline:3px solid var(--accent);outline-offset:2px}
.c-cta-24 .cta{text-align:center;max-width:560px;margin:auto;background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:calc(var(--pad)*1.6);display:grid;gap:10px;justify-items:center}.c-cta-24 h3{font-size:26px}.c-cta-24 p{color:var(--muted)}.c-cta-24 .a{display:flex;gap:10px;flex-wrap:wrap;justify-content:center;margin-top:6px}.c-cta-24 .pri{background:var(--primary);color:var(--on-primary);border:0;border-radius:var(--radius-ctl);padding:12px 24px;font-weight:700;cursor:pointer}.c-cta-24 .sec{background:none;border:1.5px solid var(--border);border-radius:var(--radius-ctl);padding:12px 24px;font-weight:700;cursor:pointer}
